sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform shader backdrop;
uniform float blur;
uniform float refraction;
uniform float angle;
uniform float highlight;
layout(color) uniform half4 color;
uniform float tint;
float h(float2 p) { return float(blurred.eval(p).a); }
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return half4(0.0);
    float e = max(blur * 0.15, 1.0);
    float2 g = float2(h(coord + float2(e, 0.0)) - h(coord - float2(e, 0.0)), h(coord + float2(0.0, e)) - h(coord - float2(0.0, e))) / (2.0 * e);
    float3 n = normalize(float3(-g * max(blur, 1.0), 1.0));
    half4 bg = backdrop.eval(coord - n.xy * refraction);
    float3 rgb = bg.a > 0.0 ? float3(bg.rgb) / float(bg.a) : float3(0.0);
    rgb = mix(rgb, rgb * float3(color.rgb), clamp(tint, 0.0, 1.0) * float(color.a));
    float a = radians(angle);
    float3 l = normalize(float3(cos(a), -sin(a), 0.6));
    float spec = pow(max(dot(reflect(-l, n), float3(0.0, 0.0, 1.0)), 0.0), 30.0);
    float shine = clamp((spec + (1.0 - n.z) * 0.5) * highlight, 0.0, 1.0);
    float alpha = max(float(bg.a), shine);
    rgb = clamp(rgb * float(bg.a) / max(alpha, 0.001) + shine, 0.0, 1.0);
    return half4(half3(rgb * alpha), half(alpha)) * src.a;
}
